with a as(select * from public.authors where open_library_id=any(array['OL9388A','OL29303A','OL2055261A','OL18283A']::text[])),w as(select * from public.works where open_library_id=any(array['OL93082W','OL7180368W','OL259026W','OL45139W']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','hlvujbrmfdlrfxdjwsmb','authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'works',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from w t),'editions',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where work_id in(select id from w) or isbn_13=any(array['9781712076972','9781234915209','9780342048960','9781774769294','9789028902626','9789022308004','9789027491022','9789035108332']::text[]) or open_library_edition_id=any(array['OL29959634M','OL34486489M','OL32276365M','OL61004144M','OL46351636M','OL24710371M','OL2988545M','OL24356700M','OL24405559M']::text[])),'reserved_range',jsonb_build_object('works',(select count(*) from public.works where id between 987116001 and 987116999),'editions',(select count(*) from public.editions where id between 987216001 and 987216999),'authors',(select count(*) from public.authors where id between 987316001 and 987316999))) as preflight;
